package com.servoc.app.exposure;

import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;

import static org.junit.Assert.*;

public class GasPpmExposureAssessmentTest {
    private static JSONObject quantified(double ppm)throws Exception{return new JSONObject().put("outcome","QUANTIFIED").put("evidence_tier","M4_HAZROB_VALIDATED").put("chemical_uid",77).put("chemical","Test gas").put("ppm",ppm).put("ppm_reportable",true).put("quantitative_occupational_interpretation_permitted",true);}
    private static ExposureRepository.Limit limit(long id,String authority,String type,double value,String unit,Double duration){return new ExposureRepository.Limit(id,77,authority,"US",type,value,unit,duration,"","SRC","R1");}
    private static JSONObject temporal(String role,double durationMin,double coveredMin,double avgPpm)throws Exception{JSONObject w=new JSONObject();w.put("role",role);w.put("duration_min",durationMin);w.put("covered_minutes",coveredMin);w.put("average_ppm",avgPpm);w.put("valid",true);return new JSONObject().put("schema","hazrob-quantitative-time-series/1").put("windows",new JSONArray().put(w));}

    @Test public void massConcentrationLimitsRemainExcludedWithoutMwTemperaturePressure()throws Exception{JSONObject a=GasPpmExposureAssessment.evaluate(quantified(10),Arrays.asList(limit(1,"OSHA","TWA",5,"mg/m3",480.0),limit(2,"OSHA","TWA",50,"ppm",480.0)),30_000);assertEquals("BELOW_AVAILABLE_PPM_REFERENCES",a.getString("state"));assertEquals(1,a.getInt("ppm_reference_count"));assertEquals(1,a.getInt("excluded_nonconvertible_mass_count"));assertEquals(1,a.getInt("excluded_non_ppm_count"));assertEquals(0.2,a.getDouble("max_ratio_to_reference"),1e-9);assertFalse(a.getJSONObject("unit_conversion_basis").getBoolean("condition_aware_mass_conversion_available"));JSONArray refs=a.getJSONArray("references");assertEquals(1,refs.length());assertEquals("ppm",refs.getJSONObject(0).getString("unit"));}

    @Test public void massConcentrationConvertsUsingSessionConditionsAndMolarMass()throws Exception{ExposureRepository.Limit mass=limit(1,"NIOSH","TWA",10,"mg/m3",480.0);JSONObject a=GasPpmExposureAssessment.evaluate(quantified(6),Collections.singletonList(mass),30_000,null,46.07,25.0,1013.25);assertEquals(1,a.getInt("converted_mass_reference_count"));assertEquals(0,a.getInt("excluded_nonconvertible_mass_count"));assertEquals(1,a.getInt("ppm_reference_count"));JSONObject r=a.getJSONArray("references").getJSONObject(0);double expected=10.0*8.31446261815324*(25.0+273.15)*1000.0/(101325.0*46.07);assertEquals(expected,r.getDouble("value_ppm"),1e-9);assertEquals(10.0,r.getDouble("original_value"),1e-9);assertEquals("mg/m3",r.getString("original_unit"));assertTrue(r.getBoolean("converted_from_mass_concentration"));assertEquals("IDEAL_GAS_SESSION_T_P_MW",r.getString("conversion_method"));JSONObject basis=a.getJSONObject("unit_conversion_basis");assertTrue(basis.getBoolean("condition_aware_mass_conversion_available"));assertEquals(46.07,basis.getDouble("molar_mass_g_mol"),1e-9);assertEquals(25.0,basis.getDouble("temperature_c"),1e-9);assertEquals(1013.25,basis.getDouble("pressure_hpa"),1e-9);}

    @Test public void m4AndReportablePpmAreMandatory()throws Exception{JSONObject p=quantified(10).put("evidence_tier","M3_ARRAY_CONSISTENT");JSONObject a=GasPpmExposureAssessment.evaluate(p,Collections.singletonList(limit(1,"OSHA","TWA",5,"ppm",480.0)),30_000);assertEquals("WITHHELD",a.getString("state"));assertEquals("m4_device_reference_calibration_required",a.getString("reason"));assertEquals(0,a.getJSONArray("references").length());}

    @Test public void idlhCrossingHasPriorityButNeverClaimsCompliance()throws Exception{JSONObject a=GasPpmExposureAssessment.evaluate(quantified(60),Arrays.asList(limit(1,"NIOSH","IDLH",50,"ppm",30.0),limit(2,"OSHA","TWA",10,"ppm",480.0)),30_000);assertEquals("IDLH_REFERENCE_CROSSED",a.getString("state"));assertEquals(2,a.getInt("crossed_reference_count"));assertEquals(1,a.getInt("action_relevant_crossed_count"));assertEquals("NOT_MADE",a.getString("compliance_determination"));assertTrue(a.getBoolean("toxic_reference_crossed"));assertTrue(a.getString("hazard_symbols").contains("☠"));JSONObject twa=a.getJSONArray("references").getJSONObject(1);assertTrue(twa.getBoolean("current_concentration_crossed"));assertFalse(twa.getBoolean("temporal_average_evaluated"));assertFalse(twa.getBoolean("action_relevant_reference_crossed"));}

    @Test public void oneMinuteAboveTwaIsImmediateCurrentWarningNotEightHourClaim()throws Exception{JSONObject a=GasPpmExposureAssessment.evaluate(quantified(50),Collections.singletonList(limit(1,"NIOSH","TWA",25,"ppm",480.0)),60_000);assertEquals("CURRENT_CONCENTRATION_ABOVE_REFERENCE",a.getString("state"));assertEquals(1,a.getInt("crossed_reference_count"));assertEquals(0,a.getInt("action_relevant_crossed_count"));JSONObject r=a.getJSONArray("references").getJSONObject(0);assertEquals(200.0,r.getDouble("percent_of_reference"),1e-9);assertTrue(r.getBoolean("current_concentration_crossed"));assertFalse(r.getBoolean("temporal_average_evaluated"));assertFalse(r.getBoolean("time_integrated_reference_crossed"));assertEquals("current_concentration_reference_warning_temporal_average_not_evaluated",r.getString("compliance_interpretation"));assertTrue(a.getBoolean("health_reference_context_warning"));assertEquals("NOT_MADE",a.getString("compliance_determination"));}

    @Test public void shortCaptureCrossingStelShowsCurrentWarningButNotTemporalExceedance()throws Exception{JSONObject a=GasPpmExposureAssessment.evaluate(quantified(20),Collections.singletonList(limit(1,"NIOSH","STEL",10,"ppm",15.0)),30_000);assertEquals("CURRENT_CONCENTRATION_ABOVE_REFERENCE",a.getString("state"));assertEquals(1,a.getInt("crossed_reference_count"));assertEquals(0,a.getInt("action_relevant_crossed_count"));JSONObject r=a.getJSONArray("references").getJSONObject(0);assertFalse(r.getBoolean("duration_coverage_satisfied"));assertFalse(r.getBoolean("temporal_average_evaluated"));assertTrue(a.getBoolean("toxic_reference_crossed"));assertTrue(a.getBoolean("health_reference_context_warning"));assertTrue(a.getString("hazard_symbols").contains("☠"));assertEquals("NOT_MADE",a.getString("compliance_determination"));}

    @Test public void fullStelWindowUsesTimeIntegratedAverage()throws Exception{JSONObject a=GasPpmExposureAssessment.evaluate(quantified(14),Collections.singletonList(limit(1,"NIOSH","STEL",10,"ppm",15.0)),15*60_000L,temporal("STEL",15,15,12));assertEquals("TIME_INTEGRATED_REFERENCE_CROSSED",a.getString("state"));assertEquals(1,a.getInt("action_relevant_crossed_count"));JSONObject r=a.getJSONArray("references").getJSONObject(0);assertTrue(r.getBoolean("temporal_average_evaluated"));assertTrue(r.getBoolean("duration_coverage_satisfied"));assertEquals(12.0,r.getDouble("time_integrated_average_ppm"),1e-9);assertTrue(r.getBoolean("time_integrated_reference_crossed"));}

    @Test public void exactDurationWindowIsMatchedWhenSameRoleHasMultipleWindows()throws Exception{JSONArray windows=new JSONArray();windows.put(new JSONObject().put("role","TWA").put("duration_min",480.0).put("covered_minutes",480.0).put("average_ppm",5.0).put("valid",true));windows.put(new JSONObject().put("role","TWA").put("duration_min",600.0).put("covered_minutes",600.0).put("average_ppm",20.0).put("valid",true));JSONObject temporal=new JSONObject().put("windows",windows);JSONObject a=GasPpmExposureAssessment.evaluate(quantified(15),Collections.singletonList(limit(1,"NIOSH","TWA",10,"ppm",600.0)),600*60_000L,temporal);JSONObject r=a.getJSONArray("references").getJSONObject(0);assertEquals(20.0,r.getDouble("time_integrated_average_ppm"),1e-9);assertTrue(r.getBoolean("time_integrated_reference_crossed"));assertTrue(r.getBoolean("duration_coverage_satisfied"));}

    @Test public void durationAloneNeverCreatesStelOrTwaExceedance()throws Exception{JSONObject a=GasPpmExposureAssessment.evaluate(quantified(20),Collections.singletonList(limit(1,"NIOSH","STEL",10,"ppm",15.0)),20*60_000L);JSONObject r=a.getJSONArray("references").getJSONObject(0);assertFalse(r.getBoolean("temporal_average_evaluated"));assertFalse(r.getBoolean("time_integrated_reference_crossed"));assertFalse(r.getBoolean("action_relevant_reference_crossed"));}

    @Test public void lflUsesVolPercentToPpmAndReportsMarginAndFlameAtFullLfl()throws Exception{ExposureRepository.Limit lfl=limit(3,"NIOSH","LFL",1.2,"%vol",null);JSONObject below=GasPpmExposureAssessment.evaluate(quantified(6000),Collections.singletonList(lfl),30_000);assertEquals(50.0,below.getDouble("percent_lfl"),1e-9);assertEquals(6000.0,below.getDouble("lfl_margin_ppm"),1e-9);assertFalse(below.getBoolean("flammability_lfl_reached"));assertFalse(below.getString("hazard_symbols").contains("🔥"));assertEquals("BELOW_LFL",below.getString("flammability_state"));assertEquals("MEASURED_PPM_BELOW_LOWER_FLAMMABILITY_LIMIT",below.getString("flammability_interpretation"));JSONObject at=GasPpmExposureAssessment.evaluate(quantified(12000),Collections.singletonList(lfl),30_000);assertEquals(100.0,at.getDouble("percent_lfl"),1e-9);assertEquals(0.0,at.getDouble("lfl_margin_ppm"),1e-9);assertTrue(at.getBoolean("flammability_lfl_reached"));assertTrue(at.getString("hazard_symbols").contains("🔥"));assertEquals("LFL_REACHED_OR_EXCEEDED",at.getString("flammability_state"));assertEquals("MEASURED_PPM_AT_OR_ABOVE_LOWER_FLAMMABILITY_LIMIT",at.getString("flammability_interpretation"));}

    @Test public void hazardPriorityUsesLargestRelativeHazardNotAbsolutePpm()throws Exception{JSONObject a=GasPpmExposureAssessment.evaluate(quantified(6),Arrays.asList(limit(1,"NIOSH","CEILING",5,"ppm",null),limit(2,"NIOSH","LFL",2.0,"%vol",null)),30_000);assertEquals(1.2,a.getDouble("toxicity_priority_ratio"),1e-9);assertEquals(0.0003,a.getDouble("lfl_ratio"),1e-9);assertEquals(1.2,a.getDouble("hazard_priority_ratio"),1e-9);assertEquals("TOXICITY",a.getString("hazard_priority_basis"));}

    @Test public void absenceOfComparableHealthAndLflReferencesIsNotReportedAsSafe()throws Exception{JSONObject a=GasPpmExposureAssessment.evaluate(quantified(1),Collections.singletonList(limit(1,"OSHA","TWA",1,"mg/m3",480.0)),30_000);assertEquals("NO_COMPARABLE_HEALTH_REFERENCES",a.getString("state"));assertEquals("NO_LFL_REFERENCE",a.getString("flammability_state"));assertEquals(0,a.getInt("ppm_reference_count"));assertEquals(1,a.getInt("excluded_nonconvertible_mass_count"));assertEquals(1,a.getInt("excluded_non_ppm_count"));assertTrue(a.isNull("hazard_priority_ratio"));}
}
